// Gửi byte điều khiển rồi dữ liệu
static void oledWrite(uint8_t control, const uint8_t *data, uint16_t len)
{
  HAL_I2C_Mem_Write(&hi2c2, OLED_I2C_ADDR, control, I2C_MEMADD_SIZE_8BIT, (uint8_t *)data, len,
                    OLED_I2C_TIMEOUT_MS);
}

// Vẽ một dòng chữ phóng đôi (2 page)
static void oledDrawLine(uint8_t line, const char *text)
{
  uint8_t buf[2][OLED_WIDTH_PX] = {0}; // [0]: page trên, [1]: page dưới
  uint8_t col = 0;

  for (; *text != '\0' && col + 12u <= OLED_WIDTH_PX; text++)
  {
    for (uint8_t i = 0; i < 6u; i++) // 5 cột font + 1 cột trống
    {
      uint8_t bits = (i < 5u) ? font5x7[(uint8_t)*text - ' '][i] : 0u;
      uint16_t wide = 0;

      for (uint8_t b = 0; b < 8u; b++) // nhân đôi theo chiều dọc
      {
        if (bits & (1u << b))
        {
          wide |= 3u << (2u * b);
        }
      }
      buf[0][col] = buf[0][col + 1] = (uint8_t)wide;
      buf[1][col] = buf[1][col + 1] = (uint8_t)(wide >> 8);
      col += 2u;
    }
  }

  // Cửa sổ ghi: cả chiều ngang, 2 page của dòng này
  const uint8_t window[] = {0x21, 0, OLED_WIDTH_PX - 1u, 0x22, (uint8_t)(2u * line), (uint8_t)(2u * line + 1u)};

  oledWrite(OLED_CTRL_CMD, window, sizeof(window));
  oledWrite(OLED_CTRL_DATA, &buf[0][0], sizeof(buf));
}

void oledInit(void)
{
  static const uint8_t initCmds[] = {
      0xAE,       // tắt hiển thị
      0xD5, 0x80, // tần số dao động mặc định
      0xA8, 0x3F, // multiplex 64 hàng
      0xD3, 0x00, // không lệch dọc
      0x40,       // dòng bắt đầu = 0
      0x8D, 0x14, // bật charge pump (nguồn nội 3.3 V)
      0x20, 0x00, // địa chỉ ngang: tự sang page kế khi hết hàng
      0xA1, 0xC8, // lật ngang + dọc để chữ đúng chiều
      0xDA, 0x12, // cấu hình chân COM cho panel 128x64
      0x81, 0xCF, // độ tương phản
      0xD9, 0xF1, // pre-charge
      0xDB, 0x40, // mức VCOMH
      0xA4,       // hiện theo RAM
      0xA6,       // không đảo màu
      0xAF        // bật hiển thị
  };

  oledWrite(OLED_CTRL_CMD, initCmds, sizeof(initCmds));
  for (uint8_t line = 0; line < OLED_LINES; line++)
  {
    oledDrawLine(line, ""); // xóa màn hình
  }
}

void oledPrintLine(uint8_t line, const char *format, ...)
{
  char text[OLED_LINE_CHARS + 1];
  va_list args;

  va_start(args, format);
  vsnprintf(text, sizeof(text), format, args);
  va_end(args);

  // I2C 400 kHz vẽ một dòng mất ~6 ms nên bỏ qua dòng không đổi
  if (strcmp(text, lineCache[line]) != 0)
  {
    strcpy(lineCache[line], text);
    oledDrawLine(line, text);
  }
}
